const CHAPTER = 2;
const TITLE = "L 形借位";
const SHORT = "L形";
const TAGLINE = "缺角就是空间，把异形当成正式解题骨架。";

function level(index, definition) {
  return createCampaignLevel({
    chapter: CHAPTER,
    index,
    chapterTitle: TITLE,
    chapterShortTitle: SHORT,
    chapterTagline: TAGLINE,
    cols: 6,
    rows: definition.rows || 8,
    ...definition,
  });
}

